from __future__ import annotations

import json
import os
from datetime import UTC, datetime


CREDENTIAL_NAMES = ["CDSAPI_URL", "CDSAPI_KEY"]
DATASET_ID = "reanalysis-era5-single-levels"


def result(*, ok: bool, status: str, summary: str, details: dict | None = None) -> dict:
    return {
        "schema_version": "access_probe.v1",
        "dataset_slug": os.environ.get("DATASET_SLUG", "reanalysis_era5_single_levels"),
        "provider": "cds",
        "ok": ok,
        "status": status,
        "checked_at": datetime.now(UTC).isoformat(),
        "credential_names": CREDENTIAL_NAMES,
        "summary": summary,
        "details": details or {},
    }


def main() -> None:
    api_url = os.environ.get("CDSAPI_URL")
    api_key = os.environ.get("CDSAPI_KEY") or os.environ.get("CDS_PERSONAL_ACCESS_TOKEN")
    timeout = int(os.environ.get("ACCESS_PROBE_TIMEOUT_SECONDS", "20"))

    if not api_url or not api_key:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="missing_credentials",
                    summary="CDS API URL or key is missing. Set CDSAPI_URL and CDSAPI_KEY.",
                )
            )
        )
        return

    try:
        from ecmwf.datastores import Client
    except ImportError:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="dependency_missing",
                    summary="The ecmwf-datastores-client package is required for this ERA5 access probe.",
                    details={"install": "python3 -m pip install cdsapi>=0.7.7"},
                )
            )
        )
        return

    try:
        client = Client(url=api_url, key=api_key, timeout=timeout, progress=False)
        account = client.check_authentication()
        client.get_collection(DATASET_ID)
        accepted_licences = client.get_accepted_licences()
        print(
            json.dumps(
                result(
                    ok=True,
                    status="verified",
                    summary="CDS credentials authenticated and the ERA5 single-levels collection is reachable.",
                    details={
                        "dataset_id": DATASET_ID,
                        "account_id_present": bool(isinstance(account, dict) and account.get("id")),
                        "accepted_licence_count": len(accepted_licences) if hasattr(accepted_licences, "__len__") else None,
                    },
                )
            )
        )
    except Exception as error:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="failed",
                    summary="CDS access probe failed through the ECMWF datastore client.",
                    details={"error_type": type(error).__name__, "error": str(error)[:500]},
                )
            )
        )


if __name__ == "__main__":
    main()
